import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Vector3 } = ctx.THREE;

  const group = new Group();
  group.name = 'journal-title';

  // Text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((item) => item.role === 'headline') || {
    text: 'Journal',
    typography: { fontSize: 96 },
  };

  // Create text mesh via fontAtlas
  const textMesh = ctx.fontAtlas.createText(headline.text, {
    fontSize: headline.typography?.fontSize ?? 96,
    color: '#e8ecf2',
    align: 'center',
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  // Sprite plane for the floating accent image
  const atlasWidth = 512;
  const atlasHeight = 320;
  const regionWidth = 512;
  const regionHeight = 320;
  const aspect = regionWidth / regionHeight;

  const planeGeo = new PlaneGeometry(aspect * 1.2, 1.2, 1, 1);

  let spriteTexture = null;
  const spriteMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const spriteMesh = new Mesh(planeGeo, spriteMaterial);
  spriteMesh.position.set(0, -0.5, -0.1);
  spriteMesh.scale.set(0.8, 0.8, 1);

  group.add(spriteMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      spriteTexture = tex;
      tex.flipY = false;

      // UV offset for atlas region (top-left at 0,0; region 512x320 in atlas)
      const uvOffsetX = 0 / atlasWidth;
      const uvOffsetY = 0 / atlasHeight;
      const uvScaleX = regionWidth / atlasWidth;
      const uvScaleY = regionHeight / atlasHeight;

      // Create UV transformation node
      const uvNode = uv().mul(vec2(uvScaleX, uvScaleY)).add(vec2(uvOffsetX, uvOffsetY));

      spriteMaterial.colorNode = tex.uv(uvNode);
      spriteMaterial.needsUpdate = true;
    });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    planeGeo.dispose();
    spriteMaterial.dispose();
    if (spriteTexture) {
      spriteTexture.dispose();
    }
  };

  return group;
}
